-- Canada deep-dive content: page, stats, file_format cards (including a 5th card
-- mapping the static page's dedicated "Provincial tax variation" .prov-table section,
-- since the renderer has no distinct section type for it), scope_transmission cards
-- (no flow-grid/lifecycle card this time), steps, penalties_related cards, 2 portals.
-- No penalty rows/table.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Canada';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'No B2B mandate — B2G via SAP Ariba', 'This deep-dive page reflects publicly available guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Canada''s B2B e-invoicing landscape remains voluntary with no mandate on the horizon — confirm current developments directly with the CRA or PSPC before making infrastructure decisions.', 'Canada''s federal government moved decisively on its own procurement; everything beyond that has stayed at the study-and-signal stage for several years running.', 'Outside federal procurement, Canada doesn''t prescribe a format at all — the requirement is about invoice content, not structure.', 'There is no B2B e-invoicing mandate in Canada, and none currently proposed on a fixed timeline. The one real, existing obligation is federal B2G — suppliers to the Government of Canada must invoice electronically via SAP Ariba. Two entirely separate worlds exist side by side: a mandated federal channel, and an unregulated everything-else.', 'What "getting ready" means here depends entirely on which side of the federal/everything-else line your business sits on.', 'No penalty framework exists for B2B non-adoption — because there''s nothing mandatory to fail to adopt.' FROM countries WHERE name_en = 'Canada';

